"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10706"],{55664(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modalidade.remanejamento_fallback_circular","status":422,"titulo":"A modalidade n\xe3o pode ser o fallback do pr\xf3prio remanejamento"},"descricao":{"codigo":"uniplus.configuracao.modalidade.remanejamento_fallback_circular","requisitos":[],"oQueAconteceu":["O campo `remanejamento.fallback` aponta para a pr\xf3pria modalidade: ele traz o mesmo c\xf3digo que a modalidade est\xe1 recebendo (a compara\xe7\xe3o \xe9 exata, letra por letra). Esse campo indica para onde as vagas passam quando a modalidade par n\xe3o as absorve, na regra de remanejamento cruzado. Uma modalidade que depende de si mesma n\xe3o tem para onde remanejar nem de onde compor vagas, e formaria um la\xe7o. Nada foi gravado.","Na atualiza\xe7\xe3o, a modalidade \xe9 procurada antes desta confer\xeancia: com um identificador inexistente a resposta \xe9 [modalidade n\xe3o encontrada](/erros/uniplus.configuracao.modalidade.nao_encontrada), mesmo que o conte\xfado enviado tamb\xe9m tivesse este problema. Numa modalidade do cat\xe1logo legal fixo esta recusa n\xe3o \xe9 emitida: se o conte\xfado altera algo al\xe9m da descri\xe7\xe3o e da base legal, vale [estrutura protegida n\xe3o edit\xe1vel](/erros/uniplus.configuracao.modalidade.estrutura_protegida_nao_editavel)."],"comoResolver":["Informe em `remanejamento.fallback` o c\xf3digo de **outra** modalidade ativa, ou omita o campo se a regra declarada n\xe3o o exige. Consulte tamb\xe9m [origem obrigat\xf3ria para \\"retira de\\"](/erros/uniplus.configuracao.modalidade.origem_obrigatoria_para_retirada_de_outra_modalidade), [origem s\xf3 para \\"retira de\\"](/erros/uniplus.configuracao.modalidade.origem_apenas_para_retirada_de_outra_modalidade), [refer\xeancia inexistente ou inativa](/erros/uniplus.configuracao.modalidade.referencia_inexistente_ou_inativa), [regra de remanejamento incoerente com a natureza](/erros/uniplus.configuracao.modalidade.natureza_remanejamento_incoerente) e [argumentos de remanejamento obrigat\xf3rios](/erros/uniplus.configuracao.modalidade.parametros_remanejamento_obrigatorio)."],"ondeAparece":["Cria\xe7\xe3o de uma modalidade (POST /api/configuracao/admin/modalidades)","Atualiza\xe7\xe3o de uma modalidade fora do cat\xe1logo legal fixo (PUT /api/configuracao/admin/modalidades/`{id}`), depois de a modalidade ser encontrada"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modalidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);